(function() {
    'use strict';

    class ChasmAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Cruzando el Abismo';
            this.version = '1.1.0';

            this.SEGMENTS = [
                { id: 'soy_comm', tam: 4200, pain: 8, wpGap: 65, cacDirect: 45, cacChannel: 28, cacDigital: 18, cacExtension: 8, churnSens: 0.7, refMult: 1.3, acv: 18 },
                { id: 'soy_large', tam: 1800, pain: 5, wpGap: 40, cacDirect: 85, cacChannel: 55, cacDigital: 40, cacExtension: 20, churnSens: 0.4, refMult: 0.8, acv: 32 },
                { id: 'cattle', tam: 3100, pain: 6, wpGap: 75, cacDirect: 55, cacChannel: 35, cacDigital: 25, cacExtension: 12, churnSens: 0.6, refMult: 1.1, acv: 22 },
                { id: 'hort', tam: 1400, pain: 9, wpGap: 55, cacDirect: 30, cacChannel: 20, cacDigital: 12, cacExtension: 5, churnSens: 0.8, refMult: 1.5, acv: 15 },
                { id: 'citrus', tam: 320, pain: 7, wpGap: 50, cacDirect: 60, cacChannel: 38, cacDigital: 30, cacExtension: 15, churnSens: 0.5, refMult: 1.2, acv: 24 },
                { id: 'sugar', tam: 180, pain: 4, wpGap: 80, cacDirect: 120, cacChannel: 75, cacDigital: 55, cacExtension: 30, churnSens: 0.3, refMult: 0.6, acv: 40 }
            ];

            this.EVENTS = [
                { id: 'mercosur_grant', rounds: [1, 2], prob: 0.25 },
                { id: 'ref_churn', rounds: [2], prob: 0.20 },
                { id: 'internet_expand', rounds: [2], prob: 0.30 },
                { id: 'gov_mandate', rounds: [3], prob: 0.35 },
                { id: 'agriglobal_offer', rounds: [3], prob: 0.15 },
                { id: 'drought', rounds: [3], prob: 0.20 },
                { id: 'competitor_freemium', rounds: [4], prob: 0.40 },
                { id: 'distributor_defects', rounds: [4], prob: 0.25 }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 1530000000,
                    arr: 846000000,
                    customers: 47,
                    monthlyBurn: 210000000,
                    wpcs: 0,
                    cci: 0,
                    cae: 0,
                    beachheadIndex: -1,
                    beachheadShare: 0,
                    competitivePosition: 50,
                    bowlingAlleySegments: 0,
                    investorScore: 50,
                    chasmCrossed: false,
                    arrHistory: [],
                    cciHistory: [],
                    roundEvents: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    beachhead: 0,
                    wpEcosystem: 45,
                    wpLocalization: 45,
                    wpReference: 45,
                    wpContent: 45,
                    gtmDirect: 55,
                    gtmChannel: 55,
                    gtmDigital: 55,
                    gtmExtension: 55,
                    pricing: 'subscription',
                    referenceInit: 'pilot',
                    compResponse: 'price',
                    defBeachhead: 150,
                    defAdjacent: 100,
                    narrative: 'growth',
                    scaling: 'channel_mgmt',
                    financing: 'bridge'
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var round = (window.mySimulation.state && window.mySimulation.state.currentPeriod) ? window.mySimulation.state.currentPeriod : 1;
            this._updateBriefing(window.mySimulation.state);

            if (round === 1) {
                var bh = document.getElementById('beachheadSelect');
                if (bh) decisions.beachhead = parseInt(bh.value);
                var eco = document.getElementById('wpEcosystem');
                var loc = document.getElementById('wpLocalization');
                var ref = document.getElementById('wpReference');
                var con = document.getElementById('wpContent');
                if (eco) decisions.wpEcosystem = parseFloat(eco.value) || 0;
                if (loc) decisions.wpLocalization = parseFloat(loc.value) || 0;
                if (ref) decisions.wpReference = parseFloat(ref.value) || 0;
                if (con) decisions.wpContent = parseFloat(con.value) || 0;
                var wpTotal = decisions.wpEcosystem + decisions.wpLocalization + decisions.wpReference + decisions.wpContent;
                if (Math.abs(wpTotal - 180) > 1) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('wp_total_warning'), 'warning');
                    return false;
                }
            } else if (round === 2) {
                var gd = document.getElementById('gtmDirect');
                var gc = document.getElementById('gtmChannel');
                var gg = document.getElementById('gtmDigital');
                var ge = document.getElementById('gtmExtension');
                if (gd) decisions.gtmDirect = parseFloat(gd.value) || 0;
                if (gc) decisions.gtmChannel = parseFloat(gc.value) || 0;
                if (gg) decisions.gtmDigital = parseFloat(gg.value) || 0;
                if (ge) decisions.gtmExtension = parseFloat(ge.value) || 0;
                var gtmTotal = decisions.gtmDirect + decisions.gtmChannel + decisions.gtmDigital + decisions.gtmExtension;
                if (Math.abs(gtmTotal - 220) > 1) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('gtm_total_warning'), 'warning');
                    return false;
                }
                var pr = document.getElementById('pricingSelect');
                var ri = document.getElementById('referenceSelect');
                if (pr) decisions.pricing = pr.value;
                if (ri) decisions.referenceInit = ri.value;
            } else if (round === 3) {
                var cr = document.getElementById('compResponseSelect');
                var db = document.getElementById('defBeachhead');
                var da = document.getElementById('defAdjacent');
                var ns = document.getElementById('narrativeSelect');
                if (cr) decisions.compResponse = cr.value;
                if (db) decisions.defBeachhead = parseFloat(db.value) || 0;
                if (da) decisions.defAdjacent = parseFloat(da.value) || 0;
                if (ns) decisions.narrative = ns.value;
                var defTotal = decisions.defBeachhead + decisions.defAdjacent;
                if (Math.abs(defTotal - 250) > 1) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('def_total_warning'), 'warning');
                    return false;
                }
            } else if (round === 4) {
                var sc = document.getElementById('scalingSelect');
                var fi = document.getElementById('financingSelect');
                if (sc) decisions.scaling = sc.value;
                if (fi) decisions.financing = fi.value;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var round = state.currentPeriod;
            var seg = this.SEGMENTS[ds.beachheadIndex >= 0 ? ds.beachheadIndex : 0];
            var events = this._rollEvents(round);
            ds.roundEvents = events;
            var eventCashBonus = 0;
            var eventWpcsModifier = 0;
            var eventDigitalBoost = 0;
            var eventAdoptionBoost = 0;
            var eventChurnHit = 0;
            var eventPricePressure = 0;
            var eventChannelDisruption = 0;
            var acquisitionOffered = false;

            for (var i = 0; i < events.length; i++) {
                var ev = events[i];
                if (ev === 'mercosur_grant') eventCashBonus = 2175000000;
                if (ev === 'ref_churn') eventWpcsModifier = -12;
                if (ev === 'internet_expand') eventDigitalBoost = 0.30;
                if (ev === 'gov_mandate') eventAdoptionBoost = 0.40;
                if (ev === 'agriglobal_offer') acquisitionOffered = true;
                if (ev === 'drought') eventChurnHit = 0.15;
                if (ev === 'competitor_freemium') eventPricePressure = 0.20;
                if (ev === 'distributor_defects') eventChannelDisruption = 0.30;
            }

            ds.cash += eventCashBonus;

            var newCustomers = 0;
            var revenue = 0;
            var costs = 0;
            var roundInvestment = 0;
            var periodProfit = 0;
            var wpcsChange = 0;
            var beachheadShareChange = 0;
            var cciValue = 0;
            var caeValue = 0;
            var bowlingChange = 0;

            if (round === 1) {
                ds.beachheadIndex = d.beachhead;
                seg = this.SEGMENTS[d.beachhead];
                var wpInvestTotal = d.wpEcosystem + d.wpLocalization + d.wpReference + d.wpContent;
                roundInvestment = wpInvestTotal * 1000000;
                var maxSingle = Math.max(d.wpEcosystem, d.wpLocalization, d.wpReference, d.wpContent);
                var concentrationBonus = (maxSingle / 180) * 0.15;
                var coverageScore = 0;
                if (d.wpEcosystem > 20) coverageScore += 0.25;
                if (d.wpLocalization > 20) coverageScore += 0.25;
                if (d.wpReference > 20) coverageScore += 0.25;
                if (d.wpContent > 20) coverageScore += 0.25;
                var rawWpcs = (100 - seg.wpGap) + (wpInvestTotal / 180) * seg.wpGap * (0.6 + concentrationBonus) * coverageScore;
                rawWpcs = Math.min(95, Math.max(10, rawWpcs));
                rawWpcs += eventWpcsModifier;
                ds.wpcs = Math.round(Math.max(0, rawWpcs));
                var painFactor = seg.pain / 10;
                var initialAdoption = Math.round(seg.tam * 0.005 * painFactor * (ds.wpcs / 100));
                newCustomers = Math.max(1, initialAdoption);
                ds.customers += newCustomers;
                var segAcv = seg.acv * 1000000;
                var newArr = newCustomers * segAcv;
                ds.arr += newArr;
                revenue = ds.arr / 4;
                costs = ds.monthlyBurn * 3 + roundInvestment;
                ds.cash += revenue - costs;
                ds.beachheadShare = Math.round((newCustomers / seg.tam) * 100 * 10) / 10;
                caeValue = (newArr > 0 && roundInvestment > 0) ? Math.round(((newArr * 3) / roundInvestment) * 10) / 10 : 0;
                ds.cae = caeValue;

            } else if (round === 2) {
                var gtmTotal = (d.gtmDirect + d.gtmChannel + d.gtmDigital + d.gtmExtension) * 1000000;
                roundInvestment = gtmTotal;
                var directEff = d.gtmDirect > 0 ? (d.gtmDirect / seg.cacDirect) : 0;
                var channelEff = d.gtmChannel > 0 ? (d.gtmChannel / seg.cacChannel) * 1.2 : 0;
                var digitalEff = d.gtmDigital > 0 ? (d.gtmDigital / seg.cacDigital) * (0.7 + eventDigitalBoost) : 0;
                var extensionEff = d.gtmExtension > 0 ? (d.gtmExtension / seg.cacExtension) * 0.4 : 0;
                var pricingMult = 1.0;
                var acvMult = 1.0;
                if (d.pricing === 'subscription') { pricingMult = 1.0; acvMult = 1.0; }
                if (d.pricing === 'bundle') { pricingMult = 0.85; acvMult = 1.4; }
                if (d.pricing === 'freemium') { pricingMult = ds.wpcs > 60 ? 1.3 : 0.5; acvMult = 0.6; }
                var refMult = 1.0;
                if (d.referenceInit === 'pilot') refMult = 1.15;
                if (d.referenceInit === 'comarketing') refMult = 1.25;
                if (d.referenceInit === 'casestudy') refMult = 1.1;
                refMult *= seg.refMult;
                var adoptionBoost = 1 + eventAdoptionBoost;
                var rawNew = (directEff + channelEff + digitalEff + extensionEff) * pricingMult * refMult * adoptionBoost * (ds.wpcs / 100);
                newCustomers = Math.max(0, Math.round(rawNew));
                ds.wpcs = Math.max(0, ds.wpcs + eventWpcsModifier);
                var churnRate = seg.churnSens * 0.05 + eventChurnHit;
                var churned = Math.round(ds.customers * churnRate);
                ds.customers = ds.customers + newCustomers - churned;
                var segAcv2 = seg.acv * 1000000 * acvMult;
                ds.arr = ds.customers * segAcv2;
                revenue = ds.arr / 4;
                costs = ds.monthlyBurn * 3 + roundInvestment;
                ds.cash += revenue - costs;
                ds.beachheadShare = Math.round((ds.customers / seg.tam) * 100 * 10) / 10;
                var totalCac = gtmTotal > 0 ? gtmTotal / Math.max(1, newCustomers) : 0;
                var ltv = segAcv2 * 3;
                caeValue = totalCac > 0 ? Math.round((ltv / totalCac) * 10) / 10 : 0;
                ds.cae = caeValue;

            } else if (round === 3) {
                roundInvestment = 250000000;
                var agriGlobalWpcs = 70;
                var agriGlobalPrice = 58000000;
                var defenseRatio = d.defBeachhead / 250;
                var adjacentRatio = d.defAdjacent / 250;
                var compEffect = 0;
                if (d.compResponse === 'price') compEffect = -5;
                if (d.compResponse === 'switching') compEffect = 15;
                if (d.compResponse === 'bowling') { compEffect = 5; bowlingChange = 1; }
                if (d.compResponse === 'partnership') compEffect = 10;
                var priceSens = 0.3;
                var wpcsDiff = ds.wpcs - agriGlobalWpcs;
                var competitivePos = 50 + wpcsDiff * 0.5 + compEffect + defenseRatio * 10;
                competitivePos = Math.min(100, Math.max(0, competitivePos));
                ds.competitivePosition = Math.round(competitivePos);
                var adoptionBoost3 = 1 + eventAdoptionBoost;
                var shareRetention = 0.85 + defenseRatio * 0.15;
                if (d.compResponse === 'price') shareRetention -= 0.05;
                ds.beachheadShare = Math.round(ds.beachheadShare * shareRetention * adoptionBoost3 * 10) / 10;
                var beachGrowth = Math.round(seg.tam * (ds.beachheadShare / 100)) - ds.customers + 47;
                if (beachGrowth < 0) beachGrowth = 0;
                var adjCustomers = 0;
                if (adjacentRatio > 0.2) {
                    var adjSegIdx = (ds.beachheadIndex + 1) % this.SEGMENTS.length;
                    var adjSeg = this.SEGMENTS[adjSegIdx];
                    adjCustomers = Math.round(adjSeg.tam * 0.01 * adjacentRatio * (ds.wpcs / 100));
                    if (adjCustomers > 0) bowlingChange = Math.max(bowlingChange, 1);
                }
                var churnRate3 = seg.churnSens * 0.04 + eventChurnHit;
                var churned3 = Math.round(ds.customers * churnRate3);
                newCustomers = beachGrowth + adjCustomers;
                ds.customers = ds.customers + newCustomers - churned3;
                ds.arr = ds.customers * seg.acv * 1000000;
                revenue = ds.arr / 4;
                costs = ds.monthlyBurn * 3 + roundInvestment;
                ds.cash += revenue - costs;
                ds.bowlingAlleySegments += bowlingChange;
                var narrativeBonus = 0;
                if (d.narrative === 'growth' && ds.arr > 1500000000) narrativeBonus = 10;
                if (d.narrative === 'defensibility' && ds.competitivePosition > 60) narrativeBonus = 15;
                if (d.narrative === 'exit' && acquisitionOffered) narrativeBonus = 20;
                ds.investorScore = Math.min(100, ds.investorScore + narrativeBonus);
                var totalCac3 = roundInvestment / Math.max(1, newCustomers);
                var ltv3 = seg.acv * 1000000 * 3;
                caeValue = totalCac3 > 0 ? Math.round((ltv3 / totalCac3) * 10) / 10 : 0;
                ds.cae = caeValue;

            } else if (round === 4) {
                var scalingCost = 180000000;
                roundInvestment = scalingCost;
                var scaleMult = 1.0;
                var churnReduction = 0;
                if (d.scaling === 'channel_mgmt') { scaleMult = 1.15; churnReduction = 0.02; }
                if (d.scaling === 'direct_expand') { scaleMult = 1.25; }
                if (d.scaling === 'platform_api') { scaleMult = 1.1; bowlingChange = 1; churnReduction = 0.03; }
                var financeCash = 0;
                var financeArrImpact = 1.0;
                if (d.financing === 'bridge') { financeCash = 3000000000; }
                if (d.financing === 'rba') { financeArrImpact = 0.92; financeCash = 1500000000; }
                if (d.financing === 'strategic') { financeCash = 2000000000; scaleMult *= 1.1; }
                ds.cash += financeCash;
                var pricePressureEffect = 1 - eventPricePressure;
                var channelEffect = 1 - eventChannelDisruption * 0.3;
                var baseGrowth = ds.customers * 0.15 * scaleMult * pricePressureEffect * channelEffect * (ds.wpcs / 100);
                newCustomers = Math.max(0, Math.round(baseGrowth));
                var churnRate4 = Math.max(0, seg.churnSens * 0.04 - churnReduction);
                var churned4 = Math.round(ds.customers * churnRate4);
                ds.customers = ds.customers + newCustomers - churned4;
                ds.arr = Math.round(ds.customers * seg.acv * 1000000 * financeArrImpact);
                ds.bowlingAlleySegments += bowlingChange;
                revenue = ds.arr / 4;
                costs = ds.monthlyBurn * 3 + roundInvestment;
                ds.cash += revenue - costs;
                ds.beachheadShare = Math.round((ds.customers / seg.tam) * 100 * 10) / 10;
                var totalCac4 = (roundInvestment + scalingCost) / Math.max(1, newCustomers);
                var ltv4 = seg.acv * 1000000 * 3;
                caeValue = totalCac4 > 0 ? Math.round((ltv4 / totalCac4) * 10) / 10 : 0;
                ds.cae = caeValue;
            }

            var runway = ds.monthlyBurn > 0 ? Math.round(ds.cash / ds.monthlyBurn) : 0;
            var chasmShareScore = Math.min(100, (ds.beachheadShare / 35) * 100);
            var chasmWpcsScore = Math.min(100, (ds.wpcs / 75) * 100);
            var chasmCompScore = ds.competitivePosition;
            cciValue = Math.round(chasmShareScore * 0.4 + chasmWpcsScore * 0.35 + chasmCompScore * 0.25);
            ds.cci = cciValue;
            ds.chasmCrossed = ds.beachheadShare >= 30 && ds.wpcs >= 70 && ds.cash > 0;
            ds.arrHistory.push(ds.arr);
            ds.cciHistory.push(cciValue);

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                round: round,
                newCustomers: newCustomers,
                totalCustomers: ds.customers,
                arr: ds.arr,
                revenue: Math.round(revenue),
                costs: Math.round(costs),
                cash: ds.cash,
                wpcs: ds.wpcs,
                cci: cciValue,
                cae: caeValue,
                beachheadShare: ds.beachheadShare,
                competitivePosition: ds.competitivePosition,
                runway: runway,
                bowlingAlley: ds.bowlingAlleySegments,
                events: events,
                acquisitionOffered: acquisitionOffered
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash', (v) => '₲' + Math.round(v / 1000000).toLocaleString() + 'M');
            uiManager.bind('arrDisplay', 'domainState.arr', (v) => '₲' + Math.round(v / 1000000).toLocaleString() + 'M');
            uiManager.bind('customersDisplay', 'domainState.customers');
            uiManager.bind('wpcsDisplay', 'domainState.wpcs', (v) => v + '/100');
            uiManager.bind('cciDisplay', 'domainState.cci', (v) => v + '/100');
            uiManager.bind('runwayDisplay', 'domainState.cash', (v) => Math.max(0, Math.round(v / 210000000)) + '');
        }

        getChartConfig() {
            return {
                arrChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: this._t('chart_arr_label'),
                            data: [],
                            borderColor: '#2e7d32',
                            backgroundColor: 'rgba(46,125,50,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
