        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var r = last.results || {};
            var finalArr = r.arr || 0;
            var baselineArr = 846000000;
            var arrGrowthIndex = finalArr / baselineArr;
            var cci = r.cci || 0;
            var cae = r.cae || 0;
            var runway = r.runway || 0;
            var bowling = r.bowlingAlley || 0;
            var cciScore = cci * 0.35;
            var arrScore = Math.min(100, (arrGrowthIndex / 3.2) * 100) * 0.25;
            var caeScore = Math.min(100, (cae / 3.0) * 100) * 0.20;
            var runwayScore = (runway >= 6 ? 100 : (runway / 6) * 100) * 0.12;
            var bowlingScore = Math.min(100, (bowling / 3) * 100) * 0.08;
            var totalScore = Math.round(cciScore + arrScore + caeScore + runwayScore + bowlingScore);
            var crossed = cci >= 60;
            var performanceKey = 'perf_notcross';
            if (totalScore >= 70) performanceKey = 'perf_excellent';
            else if (totalScore >= 50) performanceKey = 'perf_good';
            else if (totalScore >= 30) performanceKey = 'perf_partial';
            var performance = this._t(performanceKey);
            var insights = [];
            insights.push(this._t(crossed ? 'ins_crossed' : 'ins_not_crossed'));
            if (arrGrowthIndex >= 3.2) insights.push(this._t('ins_arr'));
            if (cae >= 3.0) insights.push(this._t('ins_cae'));
            if (runway < 6) insights.push(this._t('ins_runway'));
            return {
                totalScore: totalScore,
                arrGrowthIndex: Math.round(arrGrowthIndex * 10) / 10,
                cci: cci,
                cae: cae,
                chasmCrossed: crossed,
                performance: performance,
                performanceKey: performanceKey,
                insights: insights
            };
        }

        getHint(state, results) {
